import type { IntegrationsClient } from '../IntegrationsClient';
import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import {
  ReferenceDiscoveryRequestSchema,
  referenceProvider,
  type ReferenceDiscoveryRequest,
  type ReferenceCatalogPage,
} from '../../types/reference-connectors';
import {
  ReferenceReader,
  type ReferenceConnectorClient,
} from './ReferenceReader';
import { limitCosmosTraversal } from './cosmosPage';
import {
  ProfileReferenceInputSchema,
  type ProfileReferenceInput,
} from '../../types/design-profile';
import {
  REFERENCE_COLLECTION_LIMIT,
  REFERENCE_PLAN_LIMIT,
  REFERENCE_PLAN_BYTES,
  ReferencePlanRequestSchema,
  ReferencePlanSourceSchema,
  type ReferencePlanRequest,
  type ReferenceDiscovery,
} from '../../types/reference-onboarding';

interface ProfilePlanningOptions {
  records: ProfileRecords;
  integrations: Pick<IntegrationsClient, 'discoverCosmos' | 'fetchCosmos'>;
  connectors?: ReferenceConnectorClient;
  isCurrentAccount: () => boolean;
}
interface PlanBudget {
  bytes: number;
}
const PLANNING_TIMEOUT_MS = 45_000;

export class ProfilePlanning {
  private readonly reader: ReferenceReader;
  constructor(private readonly options: ProfilePlanningOptions) {
    this.reader = new ReferenceReader({
      cosmos: options.integrations,
      connectors: options.connectors,
    });
  }

  async verifyAccount(
    profile: ReferenceDiscovery['profile'],
    signal: AbortSignal,
  ) {
    this.assertActive(signal);
    await this.reader.verify(profile, signal);
    this.assertActive(signal);
  }

  async discover({
    signal: cancellation,
    ...input
  }: ReferenceDiscoveryRequest & { signal: AbortSignal }) {
    const request = ReferenceDiscoveryRequestSchema.parse(input);
    const signal = AbortSignal.any([
      cancellation,
      AbortSignal.timeout(PLANNING_TIMEOUT_MS),
    ]);
    const collections: ReferenceDiscovery['collections'] = [];
    const ids = new Set<string>();
    const cursors = new Set<string>();
    let first: ReferenceCatalogPage | undefined;
    let cursor: string | undefined;
    do {
      this.assertActive(signal);
      const page = await this.reader.discover({
        request,
        cursor,
        expectedAccountId: first?.profile.id,
        signal,
      });
      this.assertActive(signal);
      if (
        first &&
        (page.profile.id !== first.profile.id ||
          page.profile.url !== first.profile.url ||
          page.total !== first.total)
      )
        throw new Error(
          'Reference profile identity or collection count changed; discover the profile again',
        );
      first ??= page;
      if (page.total !== null && page.total > REFERENCE_COLLECTION_LIMIT)
        throw new Error(
          'This profile has too many collections; supply individual collection URLs',
        );
      for (const collection of page.collections) {
        if (ids.has(collection.id))
          throw new Error('Provider repeated a profile collection');
        ids.add(collection.id);
        collections.push(collection);
      }
      if (
        collections.length > REFERENCE_COLLECTION_LIMIT ||
        (page.total !== null && collections.length > page.total) ||
        (page.nextCursor && !page.collections.length)
      )
        throw new Error(
          'Reference profile collection coverage is inconsistent',
        );
      if (page.nextCursor && cursors.has(page.nextCursor))
        throw new Error('Provider repeated a profile cursor');
      if (page.nextCursor) cursors.add(page.nextCursor);
      cursor = page.nextCursor ?? undefined;
    } while (cursor);
    this.assertActive(signal);
    return this.options.records.plans.saveDiscovery({
      profile: first.profile,
      collections,
      total: first.total ?? collections.length,
    });
  }

  async prepare(input: ReferencePlanRequest, cancellation: AbortSignal) {
    const request = ReferencePlanRequestSchema.parse(input);
    const signal = AbortSignal.any([
      cancellation,
      AbortSignal.timeout(PLANNING_TIMEOUT_MS),
    ]);
    this.assertActive(signal);
    const discovery = this.options.records.plans.discovery(request.discoveryId);
    const selected = [...new Set(request.collectionIds)].map((id) => {
      const collection = discovery.collections.find((item) => item.id === id);
      if (!collection)
        throw new Error('Select a collection from this discovery');
      return collection;
    });
    const budget: PlanBudget = { bytes: 0 };
    const sources = [];
    for (const collection of selected)
      sources.push(
        await this.enumerate({
          profile: discovery.profile,
          collection,
          signal,
          budget,
        }),
      );
    const unique = new Map<string, ProfileReferenceInput>();
    for (const source of sources)
      for (const reference of source.references) {
        const prior = unique.get(reference.remoteId);
        if (prior && JSON.stringify(prior) !== JSON.stringify(reference))
          throw new Error(
            'A shared reference changed during planning; prepare the plan again',
          );
        unique.set(reference.remoteId, reference);
      }
    const existing = new Map(
      this.options.records
        .references()
        .filter(
          (reference) =>
            reference.provider === referenceProvider(discovery.profile),
        )
        .map((reference) => [reference.remoteId, reference]),
    );
    const reusableCount = [...unique.values()].filter((reference) => {
      const current = existing.get(reference.remoteId);
      const observation = current
        ? this.options.records.observation(current.id)
        : null;
      return (
        !reference.unsupportedReason &&
        current &&
        observation?.revision === current.revision &&
        observation.evidence !== 'provisional' &&
        JSON.stringify(
          ProfileReferenceInputSchema.parse({ ...current, media: [] }),
        ) === JSON.stringify(reference)
      );
    }).length;
    this.assertActive(signal);
    return this.options.records.plans.savePlan({
      discoveryId: discovery.id,
      runtime: request.runtime,
      sources,
      reusableCount,
    });
  }

  private assertActive(signal: AbortSignal) {
    signal.throwIfAborted();
    if (!this.options.isCurrentAccount())
      throw new Error('Profile account changed during reference planning');
  }

  async readApprovedCollections({
    profile,
    collection,
    collectionIds,
    isJobActive,
    signal,
  }: {
    profile: ReferenceDiscovery['profile'];
    collection: ReferenceDiscovery['collections'][number];
    collectionIds: readonly string[];
    isJobActive: () => boolean;
    signal: AbortSignal;
  }): Promise<ProfileReferenceInput[] | null> {
    const approved = new Set(collectionIds);
    const isCosmos = referenceProvider(profile) === 'cosmos';
    const references = new Map<string, ProfileReferenceInput>();
    const coverage = new Map<string, Set<string>>();
    const cursors = new Set<string>();
    let cursor: string | null = null;
    do {
      this.assertActive(signal);
      const page = await this.reader.read({
        profile,
        collection,
        cursor,
        signal,
      });
      this.assertActive(signal);
      if (!isJobActive()) return null;
      if (approved.has(page.collectionId)) {
        const covered = coverage.get(page.collectionId) ?? new Set<string>();
        for (const reference of page.references) {
          covered.add(reference.remoteId);
          references.set(reference.remoteId, reference);
        }
        coverage.set(page.collectionId, covered);
        if (
          page.total !== null &&
          (covered.size > page.total ||
            (page.isCollectionComplete && covered.size !== page.total))
        )
          throw new Error(
            'Reference collection coverage is incomplete; refresh the source again',
          );
      }
      cursor = isCosmos
        ? limitCosmosTraversal(page.nextCursor, approved)
        : page.nextCursor;
      if (cursor && cursors.has(cursor))
        throw new Error('Provider repeated an import cursor');
      if (cursor) cursors.add(cursor);
    } while (cursor);
    return [...references.values()];
  }

  private async enumerate({
    profile,
    collection,
    signal,
    budget,
  }: {
    profile: ReferenceDiscovery['profile'];
    collection: ReferenceDiscovery['collections'][number];
    signal: AbortSignal;
    budget: PlanBudget;
  }) {
    let cursor: string | null = null;
    const cursors = new Set<string>();
    const coverage = new Map<string, Set<string>>();
    const totals = new Map<string, number | null>();
    const references = new Map<string, ProfileReferenceInput>();
    do {
      this.assertActive(signal);
      const page = await this.reader.read({
        profile,
        collection,
        cursor,
        signal,
      });
      this.assertActive(signal);
      if (
        (totals.has(page.collectionId) &&
          totals.get(page.collectionId) !== page.total) ||
        (!page.isCollectionComplete && !page.references.length)
      )
        throw new Error(
          'Reference collection coverage changed during planning',
        );
      totals.set(page.collectionId, page.total);
      const covered = coverage.get(page.collectionId) ?? new Set<string>();
      for (const reference of page.references) {
        if (reference.provider !== referenceProvider(profile))
          throw new Error('Reference provider changed during planning');
        if (covered.has(reference.remoteId))
          throw new Error('Provider repeated an element within a collection');
        covered.add(reference.remoteId);
        const prior = references.get(reference.remoteId);
        if (prior && JSON.stringify(prior) !== JSON.stringify(reference))
          throw new Error('Reference changed during planning');
        references.set(reference.remoteId, reference);
      }
      coverage.set(page.collectionId, covered);
      if (
        page.total !== null &&
        (covered.size > page.total ||
          (page.isCollectionComplete && covered.size !== page.total))
      )
        throw new Error(
          'Reference collection coverage is incomplete; prepare the plan again',
        );
      budget.bytes += Buffer.byteLength(JSON.stringify(page.references));
      if (
        coverage.size > REFERENCE_COLLECTION_LIMIT ||
        references.size > REFERENCE_PLAN_LIMIT ||
        budget.bytes > REFERENCE_PLAN_BYTES
      )
        throw new Error(
          'Reference plan is too large; select fewer collections',
        );
      cursor = page.nextCursor;
      if (cursor && cursors.has(cursor))
        throw new Error('Provider repeated an import cursor');
      if (cursor) cursors.add(cursor);
    } while (cursor);
    return ReferencePlanSourceSchema.parse({
      collection,
      collectionIds: [...coverage.keys()],
      references: [...references.values()],
    });
  }
}
